using Xunit;

public class U03_AlarmsTests
{
    [Fact]
    public void LowVtiAlarm_AboveThreshold_Active()
    {
        // Arrange
        var threshold = 10;
        var vti = 12;

        // Act
        var alarm = new LowVtiAlarm(threshold);
        alarm.Compute(vti);

        // Assert
        Assert.True(alarm.IsActive);
    }

    [Fact]
    public void LowVtiAlarm_BelowThreshold_Inactive()
    {
        // Arrange
        var threshold = 10;
        var vti = 8;

        // Act
        var alarm = new LowVtiAlarm(threshold);
        alarm.Compute(vti);

        // Assert
        Assert.False(alarm.IsActive);
    }

    [Fact]
    public void LowVtiAlarm_Priority_Medium()
    {
        // Arrange
        var alarm = new LowVtiAlarm(10);

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.Priority);
    }

    [Fact]
    public void HighVtiAlarm_AboveThreshold_Active()
    {
        // Arrange
        var threshold = 15;
        var vti = 18;

        // Act
        var alarm = new HighVtiAlarm(threshold);
        alarm.Compute(vti);

        // Assert
        Assert.True(alarm.IsActive);
    }

    [Fact]
    public void HighVtiAlarm_BelowThreshold_Inactive()
    {
        // Arrange
        var threshold = 15;
        var vti = 12;

        // Act
        var alarm = new HighVtiAlarm(threshold);
        alarm.Compute(vti);

        // Assert
        Assert.False(alarm.IsActive);
    }

    [Fact]
    public void HighVtiAlarm_Priority_Medium()
    {
        // Arrange
        var alarm = new HighVtiAlarm(15);

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.Priority);
    }

